import os
import hmac
import hashlib
import sqlite3
import pickle
import base64
from flask import Flask, request, jsonify, session, make_response
from functools import wraps

app = Flask(__name__)
app.secret_key = os.environ.get('FLASK_SECRET', 'dev-key-change-me')

DB_PATH = os.environ.get('DB_PATH', '/data/app.db')

def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Session-Token', '')
        if not token:
            return jsonify({'error': 'unauthorized'}), 401
        # Validate token format (must be base64)
        try:
            raw = base64.b64decode(token)
            if len(raw) < 8:
                return jsonify({'error': 'invalid token'}), 401
        except Exception:
            return jsonify({'error': 'invalid token format'}), 401
        return f(*args, **kwargs)
    return decorated

@app.route('/api/v1/preferences', methods=['GET'])
@require_auth
def get_preferences():
    """Retrieve user preferences from stored blob"""
    user_id = request.args.get('user_id', '')
    if not user_id.isalnum():
        return jsonify({'error': 'invalid user_id'}), 400

    db = get_db()
    row = db.execute(
        'SELECT prefs_blob FROM user_preferences WHERE user_id = ?',
        (user_id,)
    ).fetchone()
    db.close()

    if not row:
        return jsonify({'preferences': {}})

    # Deserialize preferences
    try:
        prefs = pickle.loads(base64.b64decode(row['prefs_blob']))
    except Exception as e:
        return jsonify({'error': 'corrupt preferences', 'detail': str(e)}), 500

    return jsonify({'preferences': prefs})

@app.route('/api/v1/preferences', methods=['PUT'])
@require_auth
def set_preferences():
    """Store user preferences as serialized blob"""
    user_id = request.args.get('user_id', '')
    if not user_id.isalnum():
        return jsonify({'error': 'invalid user_id'}), 400

    data = request.get_json(force=True)
    if not isinstance(data, dict):
        return jsonify({'error': 'preferences must be object'}), 400

    # Validate preference keys
    allowed_keys = {'theme', 'language', 'timezone', 'notifications', 'layout', 'custom'}
    if not set(data.keys()).issubset(allowed_keys):
        return jsonify({'error': 'invalid preference keys'}), 400

    # Serialize and store
    blob = base64.b64encode(pickle.dumps(data)).decode('ascii')

    db = get_db()
    db.execute(
        'INSERT OR REPLACE INTO user_preferences (user_id, prefs_blob) VALUES (?, ?)',
        (user_id, blob)
    )
    db.commit()
    db.close()

    return jsonify({'status': 'saved'})

@app.route('/api/v1/preferences/import', methods=['POST'])
@require_auth
def import_preferences():
    """Import preferences from external backup format"""
    user_id = request.args.get('user_id', '')
    if not user_id.isalnum():
        return jsonify({'error': 'invalid user_id'}), 400

    content_type = request.content_type or ''
    if 'application/octet-stream' not in content_type:
        return jsonify({'error': 'content-type must be application/octet-stream'}), 415

    raw_blob = request.get_data()
    if len(raw_blob) > 65536:
        return jsonify({'error': 'payload too large'}), 413

    # Verify magic header for our backup format
    if not raw_blob.startswith(b'PREFS1'):
        return jsonify({'error': 'invalid backup format'}), 400

    payload = raw_blob[6:]  # Strip magic header

    # Deserialize to validate structure before storing
    try:
        obj = pickle.loads(payload)
    except Exception:
        return jsonify({'error': 'deserialization failed'}), 400

    if not isinstance(obj, dict):
        return jsonify({'error': 'preferences must be object'}), 400

    # Store the validated blob
    blob = base64.b64encode(raw_blob[6:]).decode('ascii')
    db = get_db()
    db.execute(
        'INSERT OR REPLACE INTO user_preferences (user_id, prefs_blob) VALUES (?, ?)',
        (user_id, blob)
    )
    db.commit()
    db.close()

    return jsonify({'status': 'imported', 'keys': list(obj.keys())})

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
